mapper.select:
SELECT id, email, password, nickname, handle, profile_image, phone
FROM users
WHERE email = #{email}

SELECT id, email, password, nickname, handle, profile_image, phone, bio
FROM users
WHERE id = #{id}

SELECT id, nickname, handle, profile_image, bio
FROM users
WHERE handle = #{handle}

SELECT EXISTS (
    SELECT 1 FROM users WHERE handle = #{handle}
)

mapper.update:
UPDATE users
SET nickname = #{request.nickname},
    handle = #{request.handle},
    profile_image = #{request.profileImage},
    bio = #{request.bio}
WHERE id = #{id}

mapper.select:
SELECT u.id, u.nickname, u.handle, u.profile_image as profileImage, u.bio,
       (SELECT COUNT(*) FROM follows WHERE target_user_id = u.id) as followerCount,
       (SELECT COUNT(*) FROM follows WHERE user_id = u.id) as followingCount,
       CASE WHEN f.id IS NOT NULL THEN true ELSE false END as isFollowing,
       CASE WHEN f_me.id IS NOT NULL THEN true ELSE false END as isFollower
FROM users u
LEFT JOIN follows f ON f.target_user_id = u.id AND f.user_id = #{currentUserId}
LEFT JOIN follows f_me ON f_me.user_id = u.id AND f_me.target_user_id = #{currentUserId}
WHERE u.handle = #{handle}
